-- BNCC Computação — habilidades oficiais usadas pelo DUDA
-- Fonte: BNCC Computação — Complemento à BNCC (arquivo fornecido ao projeto)

on conflict (skill_code) do update set
  stage = excluded.stage,
  school_year = excluded.school_year,
  axis = excluded.axis,
  competency_reference = excluded.competency_reference,
  skill_text = excluded.skill_text,
  source_page = excluded.source_page,
  source_name = excluded.source_name,
  source_status = excluded.source_status;
